{"content":"import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_TIMESTAMP_MAX_SKEW_SECONDS = 300
_TIMESTAMP_RE = re.compile(r"\A-?[0-9]+\Z")
_SIGNATURE_SCHEME = "v1"
_DIGEST_RE = re.compile(r"\A[0-9a-f]{64}\Z")
_CURRENCY_RE = re.compile(r"\A[A-Z]{3}\Z")


def _header(headers, name):
    try:
        value = headers.get(name) if hasattr(headers, "get") else None
        if value is None:
            lowered = name.lower()
            for key, candidate in headers.items():
                if isinstance(key, str) and key.lower() == lowered:
                    value = candidate
                    break
    except (AttributeError, TypeError):
        raise InvalidNotification("headers must be a mapping")
    if not isinstance(value, str):
        raise InvalidNotification("missing header: " + name)
    return value


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if isinstance(raw_body, str):
        raw_body = raw_body.encode("utf-8")
    if not isinstance(raw_body, (bytes, bytearray)):
        raise InvalidNotification("raw_body must be bytes")

    timestamp_text = _header(headers, "X-Pay-Timestamp")
    if not _TIMESTAMP_RE.match(timestamp_text):
        raise InvalidNotification("malformed timestamp header")
    timestamp = int(timestamp_text)
    if abs(timestamp - now) > _TIMESTAMP_MAX_SKEW_SECONDS:
        raise InvalidNotification("timestamp outside acceptance window")

    signature_text = _header(headers, "X-Pay-Signature")
    scheme, separator, digest = signature_text.partition("=")
    if separator != "=" or scheme != _SIGNATURE_SCHEME or not _DIGEST_RE.match(digest):
        raise InvalidNotification("malformed signature header")
    if isinstance(secret, str):
        secret = secret.encode("utf-8")
    signed_payload = timestamp_text.encode("ascii") + b"." + bytes(raw_body)
    expected_digest = hmac.new(secret, signed_payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_digest, digest):
        raise InvalidNotification("signature mismatch")

    try:
        event = json.loads(bytes(raw_body).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise InvalidNotification("malformed JSON body")
    if not isinstance(event, dict):
        raise InvalidNotification("body is not a JSON object")

    event_id = event.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("malformed event_id")
    account_id = event.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("malformed account_id")
    amount_minor = event.get("amount_minor")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification("malformed amount_minor")
    currency = event.get("currency")
    if not isinstance(currency, str) or not _CURRENCY_RE.match(currency):
        raise InvalidNotification("malformed currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
